      previousResponseId: perception.previousResponseId,
      historyLength: perception.history.length,
      pageText: perception.pageText,
      screenshotBase64: perception.screenshotBase64 ?? null
    });
    if (perception.stepIndex === 1) {
      return { action: { action: 'observe' }, previousResponseId: 'resp-one' };
    }
    if (perception.stepIndex === 2) {
      return { action: { action: 'scroll', direction: 'down' }, previousResponseId: 'resp-two' };
    }
    return { action: { action: 'done', success: true, evidence: 'condition ready' }, previousResponseId: 'resp-three' };
  }
};
const browser = {
  name: 'fake-chrome',
  startSession: async () => ({ targetRef: 'about:blank', viewport: { width: 1440, height: 900 } }),
  navigate: async (url) => ({ url, loaded: true }),
  click: async (point) => ({ ...point, clicked: true }),
  clickSelector: async (selector) => ({ selector, clicked: true }),
  waitForSelector: async (selector) => ({ selector, visible: true }),
  waitForUrl: async (url) => ({ url, matched: true }),
  dismissOverlays: async () => ({ dismissed: true }),
  inspectMedia: async () => ({ url: 'https://example.com', title: 'Fixture', mediaCount: 0, playingCount: 0, pausedCount: 0, endedCount: 0, currentTimeMax: 0, durationMax: null, readyCount: 0, blockedReasons: [], goalSatisfied: false }),
  verifyMediaPlayback: async () => ({ goalSatisfied: false, reason: 'not media', state: { url: 'https://example.com', title: 'Fixture', mediaCount: 0, playingCount: 0, pausedCount: 0, endedCount: 0, currentTimeMax: 0, durationMax: null, readyCount: 0, blockedReasons: [], goalSatisfied: false } }),
  typeText: async (text) => ({ characters: text.length, typed: true }),
  observe: async () => ({ url: 'https://example.com', title: 'Fixture', text: 'condition ready', observed: true }),
  scroll: async (direction) => ({ direction, scrolled: true }),
  pressKey: async (key) => ({ key, pressed: true }),
  captureScreenshot: async () => ({ bytes: new Uint8Array([137, 80, 78, 71]), mimeType: 'image/png', width: 2, height: 2, metadata: { url: 'https://example.com', cursorVisible: true } }),
  stop: async () => undefined
};
